create table public.growth_opportunity_locations (organization_id uuid not null references public.organizations(id) on delete cascade, opportunity_id uuid not null references public.growth_opportunities(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, primary key(opportunity_id, location_id));
create table public.growth_opportunity_contributors (organization_id uuid not null references public.organizations(id) on delete cascade, opportunity_id uuid not null references public.growth_opportunities(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, primary key(opportunity_id, user_id));
create table public.growth_opportunity_blockers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, opportunity_id uuid not null references public.growth_opportunities(id) on delete cascade, title text not null, description text not null default '', status text not null default 'open' check(status in ('open','resolved')), reported_by uuid references public.profiles(id), resolved_by uuid references public.profiles(id), resolved_at timestamptz, created_at timestamptz not null default now());
create table public.growth_opportunity_results (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, opportunity_id uuid not null references public.growth_opportunities(id) on delete cascade, metric_type text not null, expected_value numeric, actual_value numeric, unit text not null default '', recorded_by uuid references public.profiles(id), created_at timestamptz not null default now());
alter table public.growth_opportunity_locations enable row level security; alter table public.growth_opportunity_contributors enable row level security; alter table public.growth_opportunity_blockers enable row level security; alter table public.growth_opportunity_results enable row level security;
grant select,insert,update on public.growth_opportunity_locations,public.growth_opportunity_contributors,public.growth_opportunity_blockers,public.growth_opportunity_results to authenticated;
create policy "tenant growth locations" on public.growth_opportunity_locations for all to authenticated using(private.is_org_member(organization_id) or private.is_platform_owner()) with check(private.is_org_member(organization_id) or private.is_platform_owner());
create policy "tenant growth contributors" on public.growth_opportunity_contributors for all to authenticated using(private.is_org_member(organization_id) or private.is_platform_owner()) with check(private.is_org_member(organization_id) or private.is_platform_owner());
create policy "tenant growth blockers" on public.growth_opportunity_blockers for all to authenticated using(private.is_org_member(organization_id) or private.is_platform_owner()) with check(private.is_org_member(organization_id) or private.is_platform_owner());
create policy "tenant growth results" on public.growth_opportunity_results for all to authenticated using(private.is_org_member(organization_id) or private.is_platform_owner()) with check(private.is_org_member(organization_id) or private.is_platform_owner());
